css:
:root {
  --primary: #7ef6ff;
  --primary-hover: #57d2dd;
  --bg: #050608;
  --bg-alt: #0b0d12;
  --text: #f5fbff;
  --text-secondary: #a8b7c1;
  --card-bg: #0b0d12;
  --border: rgba(126, 246, 255, 0.38);
  --success: #7ef6ff;
  --warning: #ffd166;
  --error: #ff5f7a;
}

body {
  background: radial-gradient(circle at 10% 10%, rgba(126, 246, 255, 0.12), transparent 32%),
              radial-gradient(circle at 90% 0%, rgba(255, 95, 122, 0.18), transparent 36%),
              linear-gradient(135deg, #050608 0%, #0b0d12 60%, #050608 100%);
  color: var(--text);
  font-feature-settings: "ss01" 1, "ss02" 1;
}

.header {
  background: linear-gradient(90deg, rgba(126, 246, 255, 0.3), rgba(255, 95, 122, 0.2));
  border-bottom: 2px solid rgba(126, 246, 255, 0.45);
  box-shadow: 0 12px 30px rgba(126, 246, 255, 0.2);
}

.brand {
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  background: linear-gradient(90deg, #7ef6ff, #ff5f7a);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  text-shadow: 0 0 22px rgba(126, 246, 255, 0.35);
}

.board {
  background: linear-gradient(180deg, rgba(5, 6, 8, 0.95), rgba(11, 13, 18, 0.92));
  border-image: linear-gradient(90deg, rgba(126, 246, 255, 0.4), rgba(255, 95, 122, 0.3)) 1;
  border-width: 2px 0;
  border-style: solid;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.65), inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.card:hover {
  transform: translateY(-6px) skewY(-0.4deg);
  border-color: rgba(255, 95, 122, 0.75);
  box-shadow: 0 20px 44px rgba(255, 95, 122, 0.25);
}

.card .tag, .tag {
  background: #050608;
  color: var(--text);
  border: 1px solid rgba(126, 246, 255, 0.6);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  box-shadow: 0 8px 18px rgba(126, 246, 255, 0.18);
}

button, .button, .cta {
  background: linear-gradient(90deg, #050608 0%, #0b0d12 50%, #050608 100%);
  color: var(--text);
  border: 1px solid rgba(255, 95, 122, 0.6);
  border-radius: 999px;
  box-shadow: 0 12px 28px rgba(255, 95, 122, 0.3);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

button:hover, .button:hover, .cta:hover {
  transform: translateY(-2px);
  border-color: rgba(126, 246, 255, 0.9);
  box-shadow: 0 16px 40px rgba(126, 246, 255, 0.3);
}

input, textarea {
  background: #050608;
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text);
  border-radius: 8px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
